import {meadowTrifoliumPoint,bronzeArmeriaPoint,asclepiasPoint,parrotBranchTulipPoint,pinkRainLilyPoint,DOUBLE_TULIP_PROFILES,doubleTulipPoint,MINOR_TULIP_TYPES,minorTulipPoint,slenderTulipPoint,SINGLE_TULIP_PROFILES,singleTulipPoint,cannaReferencePoint,gardenAnemonePoint,alliumReferencePoint,daylilyReferencePoint,iridSpikePoint,irisReferencePoint,retailLilyPoint,freesiaReferencePoint,miniIrisPoint,hyacinthReferencePoint,narcissusCupPoint,nativeLilyPoint,martagonReferencePoint,narcissusReferencePoint,borderTulipPoint,retailTulipPoint,camassiaPoint,autumnCyclamenPoint,coumPoint,convallariaPoint,fritillariaPoint,spanishBluebellPoint,englishBluebellPoint,tecophilaeaPoint,acisPoint,fawnLilyPoint,earlySquillPoint,grapeHyacinthPoint,snowdropPoint,resedaPoint,acaenaPoint,chloranthusPoint,berzeliaPoint,asteliaPoint,convolvulusPoint,trainedVineSurfacePoint,eryngoSurfacePoint,soapwortPoint,balloonPoint,detailedFlower,drawDetailedHerb,veronicaPoint,baptisiaPoint,BAPTISIA_PROFILES,tanacetumPoint,arctotisPoint,emperorDahliaPoint,darkDahliaPoint,decorativeDahliaPoint,maxiDahliaPoint,MAXI_DAHLIA_PROFILES,rudyPoint,eucomisPoint,paraneePoint,somekawaPoint,queenMoonPoint,moonCupGeometry,rustySagePoint,gardenBellPoint,coniferShootGeometry,CONIFER_SHOOTS,hamamelidPoint,syringaLeafPoint,camelliaLeafPoint,namedTreeSkeleton,roseLeafPoint,vincaPoint,syneilesisPoint,artichokePoint} from '../site/plant-detail.js';
import {foliageKind,TRAIT_VALUES,appearanceSummary} from '../site/appearance.js';
const view=month=>({month,year:0,reference:false});
const dispose=g=>{for(const m of g.children){m.geometry?.dispose();if(m.isInstancedMesh)m.dispose();}};
test('Adenophora contrasts included versus exserted styles whorled leaves and double corollas without invented organ counts',()=>{
 const ids=['p-311a62d62f0f','p-3e7482d4a39e','p-514a17bbdbda','p-fe465b04de5e'];
 for(const [ci,id] of ids.entries())for(const [si,size] of [[ci===2?1:.3,ci===2?.5:.25,.08],[ci===2?.3:.16,ci===2?.25:.15,.035]].entries()){
  const info=CATALOG[id],p={...makePlant(id,35700+ci*10+si,1,1),height:size[0],spread:size[1],leafHeight:size[2]};let winter=0,summer=0;assert.equal(info.appearance.status,'partial');assert.equal(info.bloomKnown,false);assert.equal(info.appearance.arrangement,ci===2?'whorled':'alternate');
  for(let month=1;month<=12;month++){
   const g=plantModel(p,view(month)),label=`${id} size=${si} month=${month}`,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),matrix=new Matrix4();
   try{
    const bloom=month>=(ci===2?6:ci===3?9:8)&&month<=11,outer=count('petal-outer-adenophora'),buds=count('bud-adenophora'),double=ci===3;assert.equal(g.userData.architecture,'adenophoraArches',label);assert.ok(count('leaf-basal-adenophora')>0,label);assert.equal(outer>0,bloom,label);assert.equal(count('petal-inner-adenophora'),double?outer:0,label);assert.equal(count('calyx-lobe-adenophora'),(outer+buds)*5,label);assert.equal(count('anther-relict-adenophora'),double?0:outer*5,label);assert.equal(count('stigma-adenophora'),double?0:outer*3,label);assert.equal(count('nectary-disk-adenophora'),double?0:outer,label);assert.equal(count('style-plain-double-adenophora'),double?outer:0,label);if(double){assert.equal(info.appearance.petals,undefined);assert.equal(info.appearance.stamenCount,undefined);}if(ci===2)assert.equal(count('leaf-whorl-adenophora')%4,0,label);if(month===1)winter=count('leaf-basal-adenophora');if(month===9)summer=count('leaf-basal-adenophora');
    if(outer&&!double){const style=g.children.find(m=>m.userData.component==='style-adenophora'),cup=g.children.find(m=>m.userData.component==='petal-outer-adenophora');style.geometry.computeBoundingBox();style.getMatrixAt(0,matrix);const sl=new Vector3().setFromMatrixColumn(matrix,1).length()*(style.geometry.boundingBox.max.y-style.geometry.boundingBox.min.y);cup.getMatrixAt(0,matrix);const cl=new Vector3().setFromMatrixColumn(matrix,1).length();assert.ok(ci===2?sl>cl*1.4:sl<cl*.9,label+' style relative to corolla');}
    for(const m of g.children){const pos=m.geometry.attributes.position;for(const arr of [m.instanceMatrix.array,pos.array,m.geometry.attributes.normal.array])for(const v of arr)assert.ok(Number.isFinite(v),label);m.computeBoundingBox();const box=m.boundingBox,within=(x,y,z)=>y>=-.008&&y<p.height*1.3&&Math.max(Math.abs(x),Math.abs(z))<p.spread*.75;
     if(!within(box.min.x,box.min.y,box.min.z)||!within(box.max.x,box.max.y,box.max.z))for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);const e=matrix.elements;for(let j=0;j<pos.count;j++){const x=pos.getX(j),y=pos.getY(j),z=pos.getZ(j);assert.ok(within(e[0]*x+e[4]*y+e[8]*z+e[12],e[1]*x+e[5]*y+e[9]*z+e[13],e[2]*x+e[6]*y+e[10]*z+e[14]),`${label}: ${m.userData.component}`);}}
    }
   }finally{dispose(g);}
  }
  if(ci===2){assert.equal(winter,summer,id+' winter unverified');assert.equal(info.appearance.persistence,undefined);}else assert.ok(winter<summer,id+' reduced winter leaves');
 }
});
test('Garden bellflowers separate tall Amethyst Iris summer rest and Majestic winter leaf remains',()=>{
 const ids=['p-ca6e3fe29fb7','p-c5c0a18341ba','p-de1e1a034830'];
 for(const [ci,id] of ids.entries())for(const [si,size] of [[[.9,.5,.12],[.3,.4,.08],[.2,.3,.06]][ci],[[.3,.25,.06],[.14,.22,.04],[.1,.18,.03]][ci]].entries()){
  const info=CATALOG[id],p={...makePlant(id,35600+ci*10+si,1,1),height:size[0],spread:size[1],leafHeight:size[2]};assert.equal(info.appearance.status,'partial');assert.equal(info.bloomKnown,ci===1);
  for(let month=1;month<=12;month++){
   const g=plantModel(p,view(month)),label=`${id} size=${si} month=${month}`,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),matrix=new Matrix4();
   try{
    const bloom=(ci===0?[5,6]:ci===1?[5,6,7,9,10,11]:[4,5,6,9,10,11]).includes(month),cups=count('petal-cup-garden-bell');assert.equal(g.userData.architecture,'gardenBellShoots',label);assert.ok(count('leaf-basal-garden-bell')>0,label);assert.equal(cups>0,bloom,label);assert.equal(count('anther-relict-garden-bell'),cups*5,label);assert.equal(count('stigma-garden-bell'),cups*3,label);assert.equal(count('leaf-dead-garden-bell')>0,ci===2&&[12,1,2].includes(month),label);
    if(ci===1){assert.equal(info.appearance.persistence,undefined);assert.equal(info.leaf,'unknown');assert.match(info.latin,/portenschlagiana/);assert.ok(!info.latin.includes('Stella'));}
    for(const m of g.children){const pos=m.geometry.attributes.position;for(const arr of [m.instanceMatrix.array,pos.array,m.geometry.attributes.normal.array])for(const v of arr)assert.ok(Number.isFinite(v),label);if(m.userData.component==='petal-cup-garden-bell')assert.equal(m.geometry.userData[['gardenBellAmethystCup','gardenBellIrisStar','gardenBellMajesticCup'][ci]],true,label);m.computeBoundingBox();const box=m.boundingBox,within=(x,y,z)=>y>=-.008&&y<p.height*1.3&&Math.max(Math.abs(x),Math.abs(z))<p.spread*.75;
     if(!within(box.min.x,box.min.y,box.min.z)||!within(box.max.x,box.max.y,box.max.z))for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);const e=matrix.elements;for(let j=0;j<pos.count;j++){const x=pos.getX(j),y=pos.getY(j),z=pos.getZ(j);assert.ok(within(e[0]*x+e[4]*y+e[8]*z+e[12],e[1]*x+e[5]*y+e[9]*z+e[13],e[2]*x+e[6]*y+e[10]*z+e[14]),`${label}: ${m.userData.component}`);}}
    }
   }finally{dispose(g);}
  }
 }
 for(const angle of [0,Math.PI/5]){let previous=0;for(let i=0;i<=20;i++){const p=gardenBellPoint('gardenBellIrisStar',i/20,angle),radius=Math.hypot(p[0],p[2]);assert.ok(radius>=previous,'Iris petal surface does not fold across its clefts');previous=radius;}}
 const valley=gardenBellPoint('gardenBellIrisStar',1,Math.PI/5),tip=gardenBellPoint('gardenBellIrisStar',1,0);assert.ok(Math.hypot(valley[0],valley[2])<Math.hypot(tip[0],tip[2])*.5,'Iris has five deep visible clefts');
 const amethyst=makePlant(ids[0],35600,1,1);assert.equal(stateAt(amethyst,view(5)).flowerColor,stateAt(amethyst,view(6)).flowerColor);assert.equal(CATALOG[ids[0]].spread,null,'root spread is not canopy width');
});
test('Lantern bellflowers distinguish double cups internal spots glossy silver leaves and supported winter states',()=>{
 const ids=['p-aaff7e59fdcf','p-6adb65ad5f62','p-a64efb116d8c','p-373c93fc0ac4','p-11ca0ca1aaaf','p-cdc1771b5712'];
 for(const [ci,id] of ids.entries())for(const [si,size] of [[[.6,.5,.5,.6,.4,.5][ci],.4,.12],[.22,.22,.045]].entries()){
  const info=CATALOG[id],p={...makePlant(id,35500+ci*10+si,1,1),height:size[0],spread:size[1],leafHeight:size[2]},glossy=[1,3,4].includes(ci),basal=(glossy?'leaf-glossy-basal-':'leaf-basal-')+'lantern-bell';let winter=0,summer=0;assert.equal(info.appearance.status,'partial');assert.equal(info.bloomKnown,false);
  for(let month=1;month<=12;month++){
   const g=plantModel(p,view(month)),label=`${id} size=${si} month=${month}`,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),matrix=new Matrix4();
   try{
    const bloom=month>=5&&month<=(ci===4?8:6),outer=count('petal-outer-lantern-bell'),inner=count('petal-inner-lantern-bell'),buds=count('bud-lantern-bell');assert.equal(g.userData.architecture,'lanternBellCrowns',label);assert.ok(count(basal)>0,label);assert.equal(outer>0,bloom,label);assert.equal(inner,ci===2?outer:0,label);assert.equal(count('calyx-lobe-lantern-bell'),(outer+buds)*5,label);assert.equal(count('anther-relict-lantern-bell'),ci===2?0:outer*5,label);assert.equal(count('stigma-lantern-bell'),ci===2?0:outer*3,label);assert.equal(count('petal-inner-spot-lantern-bell')>0,bloom&&ci!==0,label);if(ci===2)assert.equal(info.appearance.stamenCount,undefined);if(month===1)winter=count(basal);if(month===6)summer=count(basal);
    for(const m of g.children){const pos=m.geometry.attributes.position;for(const arr of [m.instanceMatrix.array,pos.array,m.geometry.attributes.normal.array])for(const v of arr)assert.ok(Number.isFinite(v),label);if(m.userData.component==='petal-outer-lantern-bell')for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);assert.ok(matrix.elements[5]<0,label+' downward corolla');}m.computeBoundingBox();const box=m.boundingBox,within=(x,y,z)=>y>=-.008&&y<p.height*1.3&&Math.max(Math.abs(x),Math.abs(z))<p.spread*.75;
     if(!within(box.min.x,box.min.y,box.min.z)||!within(box.max.x,box.max.y,box.max.z))for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);const e=matrix.elements;for(let j=0;j<pos.count;j++){const x=pos.getX(j),y=pos.getY(j),z=pos.getZ(j);assert.ok(within(e[0]*x+e[4]*y+e[8]*z+e[12],e[1]*x+e[5]*y+e[9]*z+e[13],e[2]*x+e[6]*y+e[10]*z+e[14]),`${label}: ${m.userData.component}`);}}
    }
   }finally{dispose(g);}
  }
  if([0,1,3].includes(ci))assert.ok(winter<summer,id+' reduced winter leaves');else{assert.equal(winter,summer,id+' winter unverified');assert.equal(info.appearance.persistence,undefined);}
 }
 const silver=makePlant(ids[4],35540,1,1);assert.notEqual(stateAt(silver,view(10)).leafColor,stateAt(silver,view(6)).leafColor);
});
test('Nodding bellflower racemes retain the broad blue versus narrow ivory corolla and reduced winter leaves',()=>{
 const ids=['p-b221bdef7e3c','p-4ac2b3bab61f'];
 for(const [ci,id] of ids.entries())for(const [si,size] of [[ci===0?1.2:.4,ci===0?.6:.35,ci===0?.12:.08],[.22,.22,.045]].entries()){
  const info=CATALOG[id],p={...makePlant(id,35400+ci*10+si,1,1),height:size[0],spread:size[1],leafHeight:size[2]};let winter=0,summer=0;assert.equal(info.appearance.status,'partial');assert.equal(info.bloomKnown,false);assert.equal(info.appearance.inflorescence,'raceme');
  for(let month=1;month<=12;month++){
   const g=plantModel(p,view(month)),label=`${id} size=${si} month=${month}`,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),matrix=new Matrix4();
   try{
    const bloom=month>=5&&month<=6,cups=count('petal-cup-nodding-bell'),buds=count('bud-nodding-bell');assert.equal(g.userData.architecture,'noddingBellRacemes',label);assert.ok(count('leaf-basal-nodding-bell')>0,label);assert.equal(cups>0,bloom,label);assert.equal(count('stem-nodding-bell')>0,month>=4&&month<=9,label);assert.equal(count('calyx-lobe-nodding-bell'),(cups+buds)*5,label);assert.equal(count('anther-relict-nodding-bell'),cups*5,label);assert.equal(count('stigma-nodding-bell'),cups*3,label);if(month===1)winter=count('leaf-basal-nodding-bell');if(month===6)summer=count('leaf-basal-nodding-bell');
    for(const m of g.children){const pos=m.geometry.attributes.position;for(const arr of [m.instanceMatrix.array,pos.array,m.geometry.attributes.normal.array])for(const v of arr)assert.ok(Number.isFinite(v),label);if(m.userData.component==='petal-cup-nodding-bell'){assert.equal(m.geometry.userData[ci===0?'noddingBellOpenCup':'noddingBellNarrowCup'],true,label);for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);assert.ok(matrix.elements[5]<0,label+' nodding corolla');}}m.computeBoundingBox();const box=m.boundingBox,within=(x,y,z)=>y>=-.008&&y<p.height*1.3&&Math.max(Math.abs(x),Math.abs(z))<p.spread*.75;
     if(!within(box.min.x,box.min.y,box.min.z)||!within(box.max.x,box.max.y,box.max.z))for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);const e=matrix.elements;for(let j=0;j<pos.count;j++){const x=pos.getX(j),y=pos.getY(j),z=pos.getZ(j);assert.ok(within(e[0]*x+e[4]*y+e[8]*z+e[12],e[1]*x+e[5]*y+e[9]*z+e[13],e[2]*x+e[6]*y+e[10]*z+e[14]),`${label}: ${m.userData.component}`);}}
    }
   }finally{dispose(g);}
  }
  assert.ok(winter<summer,id+' winter leaf reduction');
 }
});
test('Alpine bellflowers show hairs only on the supported blue entry and keep unverified winter foliage explicit',()=>{
 const ids=['p-128d1445c3b3','p-f3e204dbda05'];
 for(const [ci,id] of ids.entries())for(const [si,size] of [[.1,.2,.03],[.06,.12,.018]].entries()){
  const info=CATALOG[id],p={...makePlant(id,35300+ci*10+si,1,1),height:size[0],spread:size[1],leafHeight:size[2]};let winter=0,summer=0;
  assert.equal(info.appearance.status,'partial');assert.equal(info.bloomKnown,false);assert.equal(info.leaf,'unknown');assert.equal(info.appearance.persistence,undefined);
  if(ci===1)assert.ok(info.appearance.unconfirmed.some(s=>s.includes('一致していません')));
  for(let month=1;month<=12;month++){
   const g=plantModel(p,view(month)),label=`${id} size=${si} month=${month}`,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),matrix=new Matrix4();
   try{
    const bloom=month>=6&&month<=8,cups=count('petal-cup-alpine-bell'),leaves=count(ci===0?'leaf-glossy-alpine-bell':'leaf-alpine-bell');assert.equal(g.userData.architecture,'alpineBellMats',label);assert.ok(leaves>0,label);assert.equal(cups>0,bloom,label);assert.equal(count('petal-hair-alpine-bell')>0,bloom&&ci===0,label);assert.equal(count('anther-relict-alpine-bell'),cups*5,label);assert.equal(count('stigma-alpine-bell'),cups*3,label);if(month===1)winter=leaves;if(month===7)summer=leaves;
    for(const m of g.children){const pos=m.geometry.attributes.position;for(const arr of [m.instanceMatrix.array,pos.array,m.geometry.attributes.normal.array])for(const v of arr)assert.ok(Number.isFinite(v),label);m.computeBoundingBox();const box=m.boundingBox,within=(x,y,z)=>y>=-.008&&y<p.height*1.3&&Math.max(Math.abs(x),Math.abs(z))<p.spread*.75;
     if(!within(box.min.x,box.min.y,box.min.z)||!within(box.max.x,box.max.y,box.max.z))for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);const e=matrix.elements;for(let j=0;j<pos.count;j++){const x=pos.getX(j),y=pos.getY(j),z=pos.getZ(j);assert.ok(within(e[0]*x+e[4]*y+e[8]*z+e[12],e[1]*x+e[5]*y+e[9]*z+e[13],e[2]*x+e[6]*y+e[10]*z+e[14]),`${label}: ${m.userData.component}`);}}
    }
   }finally{dispose(g);}
  }
  assert.equal(winter,summer,id+' leaf season remains unconfirmed');
 }
});
