test('Drumstick separates pale asymmetric florets and papery fruit cups without annual regrowth',()=>{
 const id='p-8b222ce12af1',info=CATALOG[id];assert.equal(info.appearance.architecture,'drumstickPaperyHeads');assert.equal(info.appearance.status,'partial');assert.equal(info.life,'annual');assert.equal(info.bloomKnown,false);assert.deepEqual(info.bloom,[6,7]);assert.deepEqual(info.height,[.6,1]);assert.deepEqual(info.spread,[.3,.5]);
 for(const [si,size] of [{height:.8,spread:.4,leafHeight:.42},{height:.35,spread:.25,leafHeight:.19}].entries()){
  const p={...makePlant(id,32500+si,1,1),...size};let bloomStems;
  for(let month=1;month<=12;month++){
   const v=view(month),st=stateAt(p,v),g=plantModel(p,v),tag=`Drumstick h=${p.height} m=${month}`,count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),matrix=new Matrix4();
   try{
    if(st.groundDormant){assert.equal(g.children.length,0,tag);continue;}
    assert.equal(g.userData.architecture,'drumstickPaperyHeads',tag);assert.equal(count('vein-drumstick')>0,!st.seedHeads,tag);assert.equal(count('flower-receptacle-drumstick')>0,st.bloom,tag);assert.equal(count('fruit-receptacle-drumstick')>0,st.seedHeads,tag);
    const flowers=count('flower-receptacle-drumstick'),fruits=count('fruit-receptacle-drumstick');assert.equal(count('petal-drumstick-tube'),flowers*42,tag);assert.equal(count('petal-drumstick-outer'),flowers*9*5,tag);assert.equal(count('petal-drumstick-inner'),flowers*33*5,tag);assert.equal(count('filament-drumstick'),flowers*42*4,tag);assert.equal(count('style-drumstick'),flowers*42,tag);assert.equal(count('papery-cup-drumstick'),fruits*42,tag);assert.equal(count('persistent-calyx-awn-drumstick'),fruits*42*5,tag);assert.equal(count('bract-drumstick'),count('involucre-drumstick')*10,tag);
    if(st.seedHeads){assert.equal(count('vein-drumstick'),0,tag);const cup=g.children.find(m=>m.userData.component==='papery-cup-drumstick');assert.equal(cup.geometry.userData.drumstickPaperyCup.ribs,32);assert.equal(fruits,si===0?24:6,tag);}
    if([6,9].includes(month)){const matrices=g.children.filter(m=>m.userData.component==='stem-drumstick'||m.userData.component==='peduncle-drumstick').map(m=>[...m.instanceMatrix.array]);if(!bloomStems)bloomStems=matrices;else assert.deepEqual(matrices,bloomStems,tag);}
    for(const m of g.children){const pos=m.geometry.attributes.position;for(const arr of [m.instanceMatrix.array,pos.array,m.geometry.attributes.normal.array])for(const n of arr)assert.ok(Number.isFinite(n),tag);m.computeBoundingBox();const box=m.boundingBox,within=(x,y,z)=>y>=-.005&&y<p.height*1.2&&Math.max(Math.abs(x),Math.abs(z))<p.spread*.8;
     if(!within(box.min.x,box.min.y,box.min.z)||!within(box.max.x,box.max.y,box.max.z))for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);const e=matrix.elements;for(let j=0;j<pos.count;j++){const x=pos.getX(j),y=pos.getY(j),z=pos.getZ(j);assert.ok(within(e[0]*x+e[4]*y+e[8]*z+e[12],e[1]*x+e[5]*y+e[9]*z+e[13],e[2]*x+e[6]*y+e[10]*z+e[14]),`${tag}: ${m.userData.component} actual bounds`);}}
    }
   }finally{dispose(g);}
  }
  assert.equal(stateAt(p,{...view(6),year:1}).present,false);
  const autumn={...p,start:10};assert.equal(stateAt(autumn,view(11)).present,true);assert.equal(stateAt(autumn,{...view(6),year:1}).bloom,true);assert.equal(stateAt(autumn,{...view(11),year:1}).present,false);
 }
});
