test('Korean aster loses basal leaves at flowering and retains tapered alternate stem leaves',()=>{
 const id='p-a65193340585',info=CATALOG[id],a=info.appearance;assert.equal(a.architecture,'koreanAsterShoots');assert.equal(a.status,'partial');assert.equal(info.spread,null);assert.deepEqual(info.height,[.3,.6]);assert.equal(info.bloomKnown,false);assert.deepEqual(info.bloom,[8,9,10]);assert.equal(a.leafLength,.15);assert.equal(a.arrangement,'alternate');assert.match(a.unconfirmed.join(' '),/国内写真は切り花/);
 for(const small of [false,true]){const p={...makePlant(id,29000+Number(small),1,1),height:small?.30:.60,spread:small?.22:.35,leafHeight:small?.12:.25};
  for(let month=1;month<=12;month++){
   const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),winter=[12,1,2].includes(month);if(winter){assert.equal(g.children.length,0);dispose(g);continue;}
   assert.equal(g.userData.architecture,'koreanAsterShoots');assert.equal(stateAt(p,view(month)).shootScale,1);assert.ok(count('leaf-korean-aster-cauline')>0);assert.equal(count('leaf-korean-aster-basal')>0,month<=6);assert.equal(count('branch-korean-aster')>0,month>=6);assert.equal(count('ray-korean-aster')>0,info.bloom.includes(month));const heads=count('involucre-korean-aster'),open=heads-count('bud-korean-aster');
   if(heads){assert.equal(heads,count('stem-korean-aster')/12*4);assert.equal(count('bract-korean-aster'),heads*36);assert.ok(count('ray-korean-aster')>=open*24&&count('ray-korean-aster')<=open*32);assert.equal(count('disc-floret-korean-aster'),open*100);assert.equal(g.children.find(m=>m.userData.component==='ray-korean-aster').receiveShadow,false);const cup=g.children.find(m=>m.userData.component==='involucre-korean-aster'),matrix=new Matrix4();cup.getMatrixAt(0,matrix);assert.ok(Math.abs(Math.hypot(matrix.elements[0],matrix.elements[1],matrix.elements[2])-.007)<1e-7,'head organs do not scale down with plant size');}
   assert.ok(!g.children.some(m=>/seed|fruit|hair/.test(m.userData.component)));
   for(const m of g.children){for(const arr of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok([...arr].every(Number.isFinite));m.computeBoundingBox();assert.ok(m.boundingBox.min.y>=-.008,m.userData.component);assert.ok(m.boundingBox.max.y<p.height*1.14,m.userData.component);assert.ok(Math.max(Math.abs(m.boundingBox.min.x),Math.abs(m.boundingBox.max.x),Math.abs(m.boundingBox.min.z),Math.abs(m.boundingBox.max.z))<p.spread*.80,m.userData.component);}dispose(g);
  }
 }
});
test('Marshallia has three-veined leaves and rayless heads with curled five-lobed florets',()=>{
 const id='p-3e720131ca63',info=CATALOG[id],a=info.appearance;assert.equal(a.architecture,'marshalliaHeads');assert.equal(a.status,'partial');assert.deepEqual(info.height,[.3,.45]);assert.deepEqual(info.spread,[.2,.3]);assert.equal(info.bloomKnown,false);assert.equal(a.persistence,'semiDormant');assert.deepEqual(info.bloom,[5,6]);assert.match(a.unconfirmed.join(' '),/頭花25mmは小花を含む全体径/);
 for(const small of [false,true]){const p={...makePlant(id,28900+Number(small),1,1),height:small?.22:.45,spread:small?.18:.25,leafHeight:small?.10:.17};
  for(let month=1;month<=12;month++){
   const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0),winter=[12,1,2].includes(month),tubes=count('corolla-marshallia-tube'),heads=count('involucre-marshallia');assert.equal(g.userData.architecture,'marshalliaHeads');assert.equal(stateAt(p,view(month)).groundDormant,false);assert.ok(count('leaf-marshallia-basal')>0);assert.equal(count('stem-marshallia')>0,!winter);assert.equal(tubes>0,info.bloom.includes(month));assert.equal(count('vein-marshallia-three'),(count('leaf-marshallia-basal')+count('leaf-marshallia-cauline'))*36);assert.ok(!g.children.some(m=>/ray|fruit|seed/.test(m.userData.component)));
   if(heads){assert.ok(heads<=10);assert.equal(heads,count('stem-marshallia')/10*3);assert.equal(count('corolla-marshallia-lobe'),tubes*5);assert.equal(count('anther-column-marshallia'),tubes);assert.equal(count('style-marshallia-fork'),tubes*8);assert.equal(count('bud-marshallia')+tubes,heads*70);assert.equal(g.children.find(m=>m.userData.component==='corolla-marshallia-lobe').receiveShadow,false);const cup=g.children.find(m=>m.userData.component==='involucre-marshallia'),matrix=new Matrix4();cup.getMatrixAt(0,matrix);assert.ok(Math.abs(Math.hypot(matrix.elements[0],matrix.elements[1],matrix.elements[2])-.0125*.37)<1e-7,'25mm describes the complete head, not its green core');}
   if(month===6){
    const cup=g.children.find(m=>m.userData.component==='involucre-marshallia'),matrix=new Matrix4(),centres=[];for(let i=0;i<cup.count;i++){cup.getMatrixAt(i,matrix);centres.push(new Vector3().setFromMatrixPosition(matrix));}
    let extent=0;for(const m of g.children.filter(m=>/^(corolla|anther|style|bud|bract)-marshallia|^(corolla-marshallia|anther-column-marshallia|style-marshallia)/.test(m.userData.component))){const vertices=m.geometry.attributes.position;for(let i=0;i<m.count;i++){m.getMatrixAt(i,matrix);for(let j=0;j<vertices.count;j++){const p=new Vector3().fromBufferAttribute(vertices,j).applyMatrix4(matrix);extent=Math.max(extent,Math.min(...centres.map(c=>p.distanceTo(c))));}}}
    assert.ok(extent>.009&&extent<.014,`complete flower head radial extent ${extent} stays near the 25mm species reference`);
    const tubesMesh=g.children.find(m=>m.userData.component==='corolla-marshallia-tube'),lobes=g.children.find(m=>m.userData.component==='corolla-marshallia-lobe'),tubeMatrix=new Matrix4(),lobeMatrix=new Matrix4();for(let i=0;i<tubesMesh.count;i++){tubesMesh.getMatrixAt(i,tubeMatrix);const inv=tubeMatrix.clone().invert();for(let j=0;j<5;j++){lobes.getMatrixAt(i*5+j,lobeMatrix);const root=new Vector3().setFromMatrixPosition(lobeMatrix).applyMatrix4(inv);assert.ok(Math.abs(root.y-1)<1e-5);assert.ok(Math.abs(Math.hypot(root.x,root.z)-.25)<1e-5,'five lobe roots attach to the tube rim');}}
   }
   for(const m of g.children){for(const arr of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok([...arr].every(Number.isFinite));m.computeBoundingBox();assert.ok(m.boundingBox.min.y>=-.008,m.userData.component);assert.ok(m.boundingBox.max.y<p.height*1.14,m.userData.component);assert.ok(Math.max(Math.abs(m.boundingBox.min.x),Math.abs(m.boundingBox.max.x),Math.abs(m.boundingBox.min.z),Math.abs(m.boundingBox.max.z))<p.spread*.80,m.userData.component);if(winter)assert.ok(m.boundingBox.max.y<p.height*.15,m.userData.component);}dispose(g);
  }
 }
});
