   if(heads){assert.equal(count('scape-bellium'),heads*8);assert.equal(count('bract-bellium'),heads*10);assert.ok(count('ray-bellium')>=open*10);assert.ok(count('ray-bellium')<=open*16);assert.equal(count('disc-floret-bellium'),open*35);assert.ok(count('spent-bellium')>0);assert.equal(g.children.find(m=>m.userData.component==='ray-bellium').receiveShadow,false);const cup=g.children.find(m=>m.userData.component==='involucre-bellium'),matrix=new Matrix4();cup.getMatrixAt(0,matrix);assert.ok(Math.abs(Math.hypot(matrix.elements[0],matrix.elements[1],matrix.elements[2])-.0016)<1e-7);}
