test('Dwarf mountain fleabane keeps continuous trifid rosette leaves below single hairy scapes',()=>{
 const id='p-a47e385802b3',info=CATALOG[id],a=info.appearance;assert.equal(a.architecture,'compositusRosettes');assert.equal(a.status,'partial');assert.deepEqual(info.height,[.10,.15]);assert.deepEqual(info.spread,[.15,.25]);assert.equal(info.bloomKnown,false);assert.match(a.unconfirmed.join(' '),/変種同定は未確認/);assert.equal(seasonAt(info,8).bloom,false);assert.equal(seasonAt(info,10).bloom,true);
 for(const small of [false,true]){const p={...makePlant(id,28500+Number(small),1,1),height:small?.08:.15,spread:small?.15:.20,leafHeight:small?.04:.06};
  for(let month=1;month<=12;month++){
   const g=plantModel(p,view(month)),count=k=>g.children.filter(m=>m.userData.component===k).reduce((n,m)=>n+m.count,0);if([12,1,2].includes(month)){assert.equal(g.children.length,0);dispose(g);continue;}
   assert.equal(g.userData.architecture,'compositusRosettes');assert.ok(count('leaf-compositus-woolly')>0);const blade=g.children.find(m=>m.userData.component==='leaf-compositus-woolly').geometry;assert.ok(blade.userData.continuousTrifidBlade);assert.ok(count('hair-compositus-leaf')>0);const heads=count('involucre-compositus'),open=heads-count('bud-compositus');assert.equal(heads>0,info.bloom.includes(month));assert.equal(count('scape-compositus')>0,info.bloom.includes(month));if(heads){assert.equal(count('scape-compositus'),heads*8);assert.equal(count('ray-compositus'),open*40);assert.equal(count('disc-floret-compositus'),open*65);assert.equal(count('bract-compositus-scape'),heads);assert.equal(g.children.find(m=>m.userData.component==='ray-compositus').receiveShadow,false);}
   if(month===5){const n=blade.attributes.position.count,links=Array.from({length:n},()=>[]),ix=blade.index.array;for(let j=0;j<ix.length;j+=3){const [a,b,c]=[ix[j],ix[j+1],ix[j+2]];links[a].push(b,c);links[b].push(a,c);links[c].push(a,b);}const seen=new Set([0]),todo=[0];while(todo.length)for(const j of links[todo.pop()])if(!seen.has(j)){seen.add(j);todo.push(j);}assert.equal(seen.size,n,'three lobes must remain one connected blade');}
   for(const m of g.children){for(const arr of [m.instanceMatrix.array,m.geometry.attributes.position.array,m.geometry.attributes.normal.array])assert.ok([...arr].every(Number.isFinite));m.computeBoundingBox();assert.ok(m.boundingBox.min.y>=-.008,m.userData.component);assert.ok(m.boundingBox.max.y<p.height*1.20,m.userData.component);assert.ok(Math.max(Math.abs(m.boundingBox.min.x),Math.abs(m.boundingBox.max.x),Math.abs(m.boundingBox.min.z),Math.abs(m.boundingBox.max.z))<p.spread*.75,m.userData.component);}dispose(g);
  }
 }
});
