 for(const id of ['p-132064a068ae','p-c3a33b8cb2ba']){assert.equal(CATALOG[id].spread,null);assert.match(CATALOG[id].appearance.phenologyRegion,/品種固有.*未確認/);assert.match(seasonAt(CATALOG[id],1).phase,/種から推定.*未確認/);}
