test('Japanese maple preserves connected wood through twelve months and uses Japanese flower observations',()=>{
 const p=makePlant('maple',14001,2,2);p.height=1.5;p.spread=1.5;p.leafHeight=1.5;
 let wood,scale;
 for(let month=1;month<=12;month++){
  const g=plantModel(p,view(month)),part=k=>g.children.find(m=>m.userData.component===k),winter=[12,1,2,3].includes(month);
  const branches=g.children.filter(m=>['wood-smooth','twig-maple'].includes(m.userData.component)).map(m=>[...m.instanceMatrix.array]);
  assert.ok(branches.length===2);if(wood){assert.deepEqual(branches,wood);assert.deepEqual(g.scale.toArray(),scale);}else{wood=branches;scale=g.scale.toArray();}
  assert.equal(!!part('maple'),!winter);assert.equal(!!part('petiole'),!winter);assert.equal(!!part('bud-maple'),winter);
  assert.equal(!!part('petal-maple'),month===4);assert.equal(!!part('wing-maple'),month===5);
  if(!winter)assert.equal(part('maple').count,part('petiole').count,'each surviving blade keeps its supporting petiole');
  for(const m of g.children){assert.ok([...m.instanceMatrix.array].every(Number.isFinite));assert.ok([...m.geometry.attributes.position.array].every(Number.isFinite));}dispose(g);
 }
 assert.deepEqual(CATALOG.maple.appearance.flowerMonths,[4]);assert.equal(CATALOG.maple.appearance.compoundType,undefined,'a lobed simple leaf is not a compound leaf');
});
