   assert.equal(a.arrangement,'alternate');const leaf=g.children.find(m=>m.geometry.userData.camelliaLeaf===a.shootProfile);assert.ok(leaf);assert.ok(leaf.geometry.attributes.normal.getZ(109)<-.8,'upper surface faces up after shoot rotation');
   const flower=g.children.find(m=>m.geometry.userData.camelliaFlower);assert.equal(!!flower,st.bloom,id+': flower month');
