test('Viburnum distinguishes sterile balls, lacecaps, pendant cymes, fruits and stable leafless winter wood',()=>{
 const entries=Object.entries(CATALOG).filter(([,p])=>p.appearance?.architecture==='viburnumBranches');assert.equal(entries.length,10);
 for(const [i,[id,info]] of entries.entries()){
  let wood;
  for(let month=1;month<=12;month++){
   const p=makePlant(id,7600+i,2,2),st=stateAt(p,view(month)),g=plantModel(p,view(month)),a=info.appearance,typ=a.shootProfile,sterile=['snowball','sterile'].includes(typ);
   const count=k=>g.children.filter(m=>m.userData.component.startsWith(k)).reduce((n,m)=>n+m.count,0);
   assert.ok(count('stem-viburnum')>0);assert.equal(count('petal-viburnum')>0,st.bloom,id+':'+month);
   assert.equal(count('leaf-')>0,st.leafDensity>0,id+': winter leaves');
   assert.equal(count('fruit-glossy-viburnum')>0,a.fruitMonths.includes(month),id+': fruit season');
   if(sterile){assert.equal(count('anther-viburnum'),0);assert.equal(count('stigma-viburnum'),0);assert.equal(count('fruit-glossy-viburnum'),0);}
   else if(st.bloom){assert.equal(count('anther-viburnum'),count('petal-viburnum-fertile'));assert.equal(count('stigma-viburnum')*5,count('anther-viburnum'));}
   if(typ==='onondaga'&&st.bloom){assert.ok(count('petal-viburnum-sterile')>0);assert.ok(count('petal-viburnum-fertile')>0);}
   if(typ==='snowball'&&st.leafDensity>0)assert.ok(count('gland-viburnum')>0);
   const matrices=g.children.filter(m=>m.userData.component.startsWith('stem-viburnum')||m.userData.component.startsWith('wood-viburnum')).map(m=>[m.userData.component,[...m.instanceMatrix.array]]);if(!wood)wood=matrices;else assert.deepEqual(matrices,wood,id+': stable branches');
   for(const m of g.children){assert.ok([...m.instanceMatrix.array].every(Number.isFinite),id);assert.ok([...m.geometry.attributes.position.array].every(Number.isFinite),id);}dispose(g);
  }
 }
 assert.equal(CATALOG['p-f7231750660b'].appearance.leafShape,'viburnumLobed');assert.equal(CATALOG['p-ea930400faec'].appearance.leafShape,'viburnumHairy');
 assert.match(CATALOG['p-0df95eda76e4'].appearance.unconfirmed.join(' '),/同じブルーマフィン同士では受粉相手にならず/);
 assert.notEqual(seasonAt(CATALOG['p-294e23fec795'],4).leafColor,seasonAt(CATALOG['p-294e23fec795'],7).leafColor);
});

