  if(st.bloom){const flowers=count('corolla-calamintha');assert.equal(count('anther-calamintha'),flowers*4);assert.equal(count('upperLip-calamintha'),flowers*2);assert.equal(count('petal-calamintha-spots'),flowers*3);assert.equal(count('stigma-calamintha'),flowers*2);}
  if(['white','grandiflora'].includes(typ)&&[12,1,2].includes(month)&&!st.bloom){assert.equal(count('stem-calamintha'),0);assert.equal(count('leaf-calamintha'),44);}else assert.ok(g.children.some(m=>m.geometry.userData.squareStem));
  for(const m of g.children){assert.ok([...m.instanceMatrix.array].every(Number.isFinite),id);assert.ok([...m.geometry.attributes.position.array].every(Number.isFinite),id);}dispose(g);
