test('refined soapworts retain three leaf ribs angled calyces and two styles without inventing two pistils',()=>{
 const ids=['p-825e967e9c4a','p-32106ff38f0a','p-91f07ff1c009'];
 for(const [i,id] of ids.entries())for(const [height,spread] of [[i===0?.18:.8,i===0?.55:.60],[i===0?.10:.25,.22]])for(let month=1;month<=12;month++){
  const p=makePlant(id,35900+i*10,2,2);p.height=height;p.spread=spread;p.leafHeight=height*.45;const g=plantModel(p,view(month)),parts=g.children.map(m=>m.userData.component);
  for(const m of g.children)assert.ok([...m.instanceMatrix.array].every(Number.isFinite),`${id} month${month}`);
  assert.equal(CATALOG[id].appearance.status,'partial');assert.equal(CATALOG[id].appearance.stamenCount,10);assert.equal(CATALOG[id].appearance.pistilCount,undefined);
  if(month===6){assert.ok(parts.includes('vein-leaf-soapwort'));assert.ok(parts.includes('anther-soapwort'));assert.ok(g.children.some(m=>m.geometry.userData[i===2?'cowherbCalyx':'soapwortCalyx']));}
  if(month===1&&i===0)assert.equal(parts.length,0);if(month===1&&i===1){assert.ok(parts.some(k=>k.startsWith('leaf')));assert.ok(!parts.includes('stem'));}dispose(g);
 }
 const pieces=[];detailedFlower({add:(shape,kind)=>pieces.push({shape,kind}),branch:(a,b,r,c,kind)=>pieces.push({kind})},{x:0,y:0,z:0,r:.006,color:'#d8a2bd',shape:'cowherbFlower'},{bud:'bud',rand:()=>.5,shade:(_,c)=>c});assert.equal(pieces.filter(p=>p.kind==='anther-soapwort').length,10);assert.equal(pieces.filter(p=>p.kind==='style-soapwort').length,2);assert.equal(pieces.filter(p=>p.shape==='soapwortRoundBlade').length,5);
 const ridge=soapwortPoint('cowherbCalyx',.5,0),valley=soapwortPoint('cowherbCalyx',.5,Math.PI/5);assert.ok(Math.hypot(...[ridge[0],ridge[2]])>Math.hypot(...[valley[0],valley[2]])*1.2);
 for(const type of ['rockSoapwortLeaf','tallSoapwortLeaf','cowherbLeaf','soapwortCalyx','cowherbCalyx','soapwortLongBlade','soapwortRoundBlade'])for(let t=0;t<=30;t++)assert.ok(soapwortPoint(type,t/30,type.endsWith('Calyx')?1.1:.8).every(Number.isFinite));
});

