 assert.ok(cannaReferencePoint('cannaBroadStaminode',.5,1)[0]>cannaReferencePoint('cannaNarrowStaminode',.5,1)[0]*1.7);assert.ok(cannaReferencePoint('cannaReflexedLip',1,0)[1]<0,'labellum reflexes below the mouth');assert.deepEqual(CATALOG[ids[1]].colors,['orange']);assert.equal(CATALOG[ids[0]].latin,"Canna 'Schduagert'");assert.equal(CATALOG[ids[3]].appearance.leafPattern,'cannaRedVeins');assert.ok(!CATALOG[ids[1]].latin.includes('Pretoria'));
