 const id='p-ff41c5e8521e',info=CATALOG[id],a=info.appearance;assert.equal(info.latin,"Eucomis comosa 'Sparkling Burgundy'");assert.deepEqual(info.height,[.5,.8]);assert.deepEqual(info.spread,[.4,.6]);assert.equal(info.life,'perennial');assert.equal(info.bloomKnown,false);assert.equal(a.flowerTiming,'season-reference');assert.equal(a.architecture,'bronzeEucomis');assert.equal(a.status,'partial');assert.equal(a.petals,6);assert.equal(a.stamenCount,6);assert.notEqual(seasonAt(info,4).leafColor,seasonAt(info,8).leafColor);assert.notEqual(seasonAt(info,8).leafColor,seasonAt(info,10).leafColor);
